BEGIN; DO $$ BEGIN IF md5(pg_get_functiondef('public.publish_jra_live_race(uuid)'::regprocedure))<>'1283f2b810147ff2e3e2d8a7d149b37d' THEN RAISE EXCEPTION 'RPC_DEFINITION_CHANGED'; END IF; IF NOT has_function_privilege('service_role','public.publish_jra_live_race(uuid)','EXECUTE') THEN RAISE EXCEPTION 'SERVICE_PRIVILEGE_MISSING'; END IF; END $$; REVOKE EXECUTE ON FUNCTION public.publish_jra_live_race(uuid) FROM PUBLIC,anon,authenticated; DO $$ BEGIN IF has_function_privilege('anon','public.publish_jra_live_race(uuid)','EXECUTE') OR has_function_privilege('authenticated','public.publish_jra_live_race(uuid)','EXECUTE') OR NOT has_function_privilege('service_role','public.publish_jra_live_race(uuid)','EXECUTE') THEN RAISE EXCEPTION 'ACL_CHECK_FAILED'; END IF; END $$; COMMIT; SELECT has_function_privilege('anon','public.publish_jra_live_race(uuid)','EXECUTE') as anon,has_function_privilege('authenticated','public.publish_jra_live_race(uuid)','EXECUTE') as authenticated,has_function_privilege('service_role','public.publish_jra_live_race(uuid)','EXECUTE') as service_role;
